fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // Requires that k is a valid index for the list
    // Ensures that the returned vector has one less element than the input list
    // and does not contain the k-th element (0-based index)
    // Invariant: new_list always contains elements from list except the k-th element
    // Decreases clause: the length of the list decreases by 1
    // The function is specified to ensure that the input list is not empty and k is valid
    // The function will return a new vector that is a copy of the original list without the k-th element

    // Requires: list.len() > 0 && k < list.len() + 1
    // Ensures: result.len() == list.len() - 1 && !result.contains(&list[k - 1])
    let mut new_list = Vec::with_capacity(list.len() - 1);
    
    // Invariant: new_list.len() == i
    // where i is the number of elements added to new_list so far
    for (i, &value) in list.iter().enumerate() {
        // Skip the element at position k-1 (0-based index)
        if i != k - 1 {
            new_list.push(value);
            // Assert that new_list does not contain the k-th element
            // Assert: !new_list.contains(&list[k - 1])
        }
    }
    
    new_list
}